from itertools import product
def region_sets(L,R,lbg,rbg):
    A={(i,k) for i in range(len(L)) for k in range(len(L[0])) if L[i][k]!=lbg}
    B={(i,k) for i in range(len(R)) for k in range(len(R[0])) if R[i][k]!=rbg}
    return A,B
def revrows(S,h,w): return {(h-1-i,k) for i,k in S}
def revcols(S,h,w): return {(i,w-1-k) for i,k in S}
def analyze(name, Li,Ri, lbg,rbg, out):
    A,B=region_sets(Li,Ri,lbg,rbg)
    h,w=len(Li),len(Li[0])
    th={(i,k) for i in range(h) for k in range(w) if out[i][k]==3}
    ops={'A&B':A&B,'A&~B':A-B,'~A&B':B-A,'A|B':A|B,'A^B':A^B}
    for rn,rv in ops.items():
        if th==rv: print(name,rn,'MATCH')
    # flips of B
    for fr,fc in product([0,1],[0,1]):
        Bf=B
        if fr: Bf=revrows(Bf,h,w)
        if fc: Bf=revcols(Bf,h,w)
        for rn,rv in {'A&Bf':A&Bf,'A&~Bf':A-Bf}.items():
            if th==rv: print(name,rn,f'flip=({fr},{fc})','MATCH')
    print(name,'|A|',len(A),'|B|',len(B),'|threes|',len(th))
analyze('demo1',[r[:10] for r in di],[r[11:] for r in di],8,2,do_)
